# 计划书 §2 第 2 行字面值 (source: master-plan)
EXPECTED = {'http_status': ('==', 200), 'checksum_match': ('==', True)}  # 两条: 状态码 + 校验和


def test_gen_gate_count_matches_spec(spec_section):
    """门禁条目数必须恰好为 2 (http_status + checksum_match), 不多不少。"""
    assert len(spec_section["gates"]) == 2  # 恰为 2: 多一条即有人私自加门禁或计划书已漂移


def test_gen_gates_match_master_plan(spec_section):
    """每个门禁的名称、比较符与阈值都必须与 master-plan 字面值一致。

    阈值漂移 (例如 200 改成 206、True 改成 False) 会让「成功」的定义悄悄
    变化, 这里逐项钉死。
    """
    gates = {g["name"]: g for g in spec_section["gates"]}  # 名字为键: 顺序无关, 只按名逐条钉
    for name, (cmp_, value) in EXPECTED.items():                                             # 遍历计划书字面值而不是 spec 自身, 差集即为漂移
        assert name in gates, f"gate {name} 缺失于 spec"  # 缺条比阈值错更隐蔽: 门禁直接消失
        assert gates[name]["cmp"] == cmp_, f"gate {name} cmp 漂移"  # 比较符换了 = 判定方向反了
        assert gates[name]["value"] == value, f"gate {name} 阈值漂移"


def test_gen_gate_thresholds_are_decidable(spec_section):
    """阈值类型可判定: 数值门禁可比较, 布尔门禁为恒等。

    ``==`` 门禁的 value 只允许标量; 其余比较符要求数值且排除 bool —
    否则门禁求值时会因类型不匹配静默失败或误判。
    """
    for g in spec_section["gates"]:
        v = g["value"]
        if g["cmp"] == "==":
            assert isinstance(v, (bool, int, float, str))  # 恒等门禁: bool 本身就是有意义的阈值
        else:
            # 比较型必须排除 bool: False 会被当成 0 静默通过
            assert isinstance(v, (int, float)) and not isinstance(v, bool)                  # 比较型阈值必须可与结果比大小: 字符串阈值会在求值期才炸
